/**
 * Jednoduchý dvojjazyčný prekladový systém (EN predvolene, SK voliteľne).
 * Použitie: o3dai_t( 'key' ) alebo o3dai_t( 'key', array( 'x' => $val ) ).
 */
class O3DAI_I18n {

	protected static $lang = null;

	public static function lang() {
		if ( null === self::$lang ) {
			$s = o3dai_get_settings();
			self::$lang = ( 'sk' === ( $s['ui_lang'] ?? 'en' ) ) ? 'sk' : 'en';
		}
		return self::$lang;
	}

	public static function reset() {
		self::$lang = null;
	}

	public static function t( $key, $args = array() ) {
		$dict = self::dict();
		$lang = self::lang();
		$str  = $dict[ $key ][ $lang ] ?? ( $dict[ $key ]['en'] ?? $key );
		if ( $args ) {
			foreach ( $args as $k => $v ) {
				$str = str_replace( '{' . $k . '}', $v, $str );
			}
		}
		return $str;
	}

